import requests
import random

def check_response(response):
  """Checks if a response is 'ok' or 'fail' and handles exceptions."""
  if response.status_code == 200:
    return True
  else:
    return False

def main():
  """Calls the authentication and data retrieval functions."""
  try:
    # Authenticate to the database
    username = "YOUR_USERNAME"  # Replace with your username
    password = "YOUR_PASSWORD"  # Replace with your password
    response = requests.get("https://www.example.gov/login?username=" + username + "&password=" + password, timeout=5)  # Replace with your actual URL
    if check_response(response):
      print("Authentication successful!")
    else:
      print("Authentication failed. Check credentials.")
  except requests.Timeout:
    print("Connection Timeout. Check your internet connection.") 

  try:
    # Retrieve data from the database
    response = requests.get("https://www.example.gov/data?key=YOUR_KEY", timeout=5)
    if check_response(response):
      print("Data retrieved successfully!")
    else:
      print("Data retrieval failed.")
  except requests.Timeout:
    print("Connection Timeout. Check your internet connection.")

if __name__ == "__main__":
  main()
